import {EXAMPLE_BRIEF,PRIORITIES,briefPreview,briefField} from './brief-model.mjs';
import {money,dateLabel,ROUTES} from './model.mjs';
import {unreadNotices} from './notifications.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function briefDialog(text,icon){return `<div class="dialog-content brief-intro"><h3>From a short request to a plan you can inspect.</h3><p>Local AI suggests a planning priority. Explicit limits are read from your text, and the route model calculates the options.</p></div><div class="brief-grid"><section class="brief-input"><form id="planning-brief-form"><label for="planning-brief">Your planning request <span>In English</span></label><div class="brief-input-frame"><textarea id="planning-brief" name="brief" rows="6" maxlength="600" required aria-describedby="brief-help">${esc(text||EXAMPLE_BRIEF)}</textarea></div><p id="brief-help">Use EUR, an explicit date and t CO2e for limits. Unmentioned limits stay as they are.</p><div class="brief-examples"><button type="button" data-action="brief-example" data-value="time">Arrival matters most</button><button type="button" data-action="brief-example" data-value="carbon">A lower footprint</button></div><button class="button primary brief-run" type="submit" data-brief-run>Load model & interpret ${icon('arrow',16)}</button></form><p class="brief-download">About 50 MB on first use, including a 23 MB model.</p><p class="brief-runtime-status" role="status"></p><label class="brief-file-progress" hidden>Current file<progress max="100"></progress></label><button class="text-button brief-stop" data-action="brief-stop" hidden>Stop interpretation</button><button class="text-button brief-rules" data-action="brief-rules">Preview parsed limits without AI</button><details class="brief-privacy"><summary>Model & privacy</summary><p>A small MiniLM model compares your wording with cost, arrival, emissions and balanced priorities. It runs in a Web Worker on this device. It does not invent prices, dates, routes or rationale.</p><p>First use downloads files from Hugging Face and jsDelivr. The brief is not sent to an inference endpoint. Offline reuse depends on retained browser files. A suggested priority can be wrong; review it before applying.</p><div class="brief-model-controls" hidden><button class="text-button" data-action="brief-unload">Unload model</button><button class="text-button" data-action="brief-remove">Remove model files</button></div></details></section><section class="brief-output" aria-label="Planning preview" data-brief-output>${briefOutput({},icon)}</section></div><footer class="dialog-footer brief-footer"><span>${icon('lock',15)} Preview first. Apply only when ready.</span><span>No booking · No paid API</span></footer>`;}

export function briefOutput({result,choice,current=true,errors=[]},icon){
 if(errors.length)return `<div class="brief-problem" role="alert">${icon('alert',22)}<h3>A few details need checking.</h3><ul>${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`;
 if(result&&!current)return `<div class="brief-problem" role="status">${icon('reset',22)}<h3>The brief or workspace changed.</h3><p>Interpret again to refresh the limits, route calculations and priority.</p></div>`;
 if(!result)return `<div class="brief-welcome"><span class="brief-symbol">${icon('sliders',26)}</span><span class="brief-kicker">BRIEF → LIMITS → ROUTE OPTIONS</span><h3>Make the request<br>concrete.</h3><p>“Getting there sooner matters more than the lowest price” can become an arrival-first comparison.</p><ol><li>Read the explicit planning limits.</li><li>Review the suggested priority.</li><li>Inspect the calculated route before applying.</li></ol><small>The current workspace stays unchanged.</small></div>`;
 const priority=choice||result.priority,preview=briefPreview(result.parsed,priority);
 return `<div class="brief-result"><span class="brief-kicker">${result.mode==='rules'?'RULES-ONLY PREVIEW · NO MODEL RUNNING':'ON-DEVICE INTERPRETATION'}</span><h3 tabindex="-1" data-brief-result-heading>Review what the request means.</h3><dl class="brief-limits">${['budget','deadline','emissions'].map(key=>`<div><dt>${{budget:'Total budget',deadline:'Arrival deadline',emissions:'CO₂e limit'}[key]}</dt><dd>${esc(briefField(key,result.parsed.settings[key]))}<small>${result.parsed.sources[key]?`From “${esc(result.parsed.sources[key])}”`:'Kept from your workspace'}</small></dd></div>`).join('')}</dl><div class="brief-priority"><strong>${choice?'Your chosen priority':result.priority?'Suggested priority':'Choose a priority'}</strong><p>${result.mode==='rules'?'Choose the priority yourself; no AI is running.':result.priority?'The model read the preference in your wording. You can change it.':'The wording did not indicate a clear priority. Choose one to continue.'}</p><div role="group" aria-label="Review planning priority">${PRIORITIES.map(p=>`<button type="button" data-action="brief-priority" data-value="${p.id}" aria-pressed="${priority===p.id}">${p.name}</button>`).join('')}</div></div>${preview?`<article class="brief-route"><span class="brief-kicker">CALCULATED FROM THE EXISTING ROUTE MODEL</span><h4>${preview.route?esc(preview.route.short):'No route meets these limits'}</h4>${preview.route?`<div class="brief-route-metrics"><span>${money(preview.route.cost)}<small>Total logistics cost</small></span><span>${dateLabel(preview.route.arrival)}<small>Estimated arrival</small></span><span>${preview.route.co2.toFixed(1)} t<small>Transport CO₂e</small></span></div><p>${preview.eligible} of 6 corridors meet all three limits. Current fuel and port-delay assumptions are retained.</p>`:'<p>You can apply the limits to inspect why the routes fail, then adjust them. No route has been selected by AI.</p>'}<button class="button primary" data-action="brief-apply">Apply ${preview.route?'preview':'limits'} to workspace ${icon('arrow',15)}</button></article>`:''}<p class="brief-boundary">Applying changes planning settings only. Saved decisions stay intact. Write your own rationale before saving a scenario.</p></div>`;
}

export function inboxView(records,filter,icon,saved){
 const unread=unreadNotices(records),visible=filter==='unread'?records.filter(n=>!n.read):records;
 return `<div class="dialog-content inbox-intro"><div><span class="brief-kicker">LOCAL PLANNING ACTIVITY</span><p>Checks and saved work in this browser. No carrier push alerts.</p></div><button class="text-button" data-action="notice-read-all" ${unread?'':'disabled'}>Mark all read</button></div><div class="inbox-filters" role="group" aria-label="Notification filter"><button data-action="notice-filter" data-value="all" aria-pressed="${filter==='all'}">All <span>${records.length}</span></button><button data-action="notice-filter" data-value="unread" aria-pressed="${filter==='unread'}">Unread <span>${unread}</span></button></div><div class="inbox-list">${visible.length?visible.map(n=>{const exists=!n.scenarioId||saved.some(r=>r.id===n.scenarioId);const route=ROUTES.find(r=>r.id===n.routeId);return `<article class="inbox-item ${n.read?'is-read':'is-unread'}"><span class="inbox-dot" ${n.read?'hidden':''} aria-label="Unread"></span><div class="inbox-item-copy"><span class="inbox-kind">${{baseline:'Plan check',limits:'Limits changed',ranking:'Route ranking',saved:'Scenario saved',import:'Collection imported',brief:'Planning brief'}[n.kind]}<time>${new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(n.createdAt))}</time></span><h3>${esc(n.title)}</h3><p>${esc(n.detail)}</p><div class="inbox-item-actions">${exists?`<button class="text-button" data-action="notice-open" data-id="${esc(n.id)}">${n.scenarioId?'View saved assumptions':route?'Inspect route now':'Open saved scenarios'} ${icon('arrow',13)}</button>`:'<span class="inbox-missing">The saved scenario was removed.</span>'}<button class="text-button inbox-read" data-action="notice-toggle" data-id="${esc(n.id)}">${n.read?'Mark unread':'Mark read'}</button></div></div></article>`;}).join(''):`<div class="inbox-empty">${icon('check',29)}<h3>${records.length?'You’re caught up.':'No planning events yet.'}</h3><p>${records.length?'Your earlier events remain in All.':'Planning checks and saved scenarios will appear here.'}</p></div>`}</div><footer class="dialog-footer inbox-footer"><span>Opening an earlier event inspects the current route; it never restores old limits.</span><button class="button primary" data-action="close">Done</button></footer>`;
}
